# WAR ARENA - Payment Rails (Stars + TON webhook/verify + settlement) - Installer
# Verifies a provider payment event and credits balance atomically (idempotent).
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-payment-rails.ps1
$ErrorActionPreference = "Stop"
Write-Host "WAR - Payment Rails installer" -ForegroundColor Cyan
function Write-B64([string]$Path,[string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path,[System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/product/payment/paymentWebhook.ts" ""
Write-B64 "src/product/payment/railVerifiers.ts" ""
Write-B64 "tests/unit/paymentWebhook.test.ts" ""

Write-Host ""; Write-Host "Verifying gate ..." -ForegroundColor Cyan
npx tsc --noEmit; if ($LASTEXITCODE -ne 0){ throw "typecheck failed" }
npx vitest run
Write-Host ""; Write-Host "Payment rails installed. Expected: 934 passed + 1 skipped, 441 guards." -ForegroundColor Green
